"""Generate the reference documents straight from code (they cannot drift from what ran).

    python -m rs2610.make_docs
"""
from __future__ import annotations

from collections import Counter
from pathlib import Path

from rs2610.common.data import datasets
from rs2610.study_a.tasks import build_all
from rs2610.study_b.variants import INSERTED_POST, trapped

OUT = Path(__file__).resolve().parent / "outputs"


def study_b_dictionaries() -> None:
    lines = ["# Study B — datasets and dictionaries", "",
             "Generated by `python -m rs2610.make_docs` from `common/data.py` and `study_b/variants.py`.",
             "Sections marked **evaluation authority** are never shown to any model.", ""]
    for ds in datasets("B"):
        v = trapped(ds)
        t = v.truth
        lines += [f"## {ds.dataset_id} ({ds.split}, {ds.family}, {ds.task_type})", "", f"*Description:* {v.description}", "",
                  "| Column | Dictionary text (conditions C/D/E) |", "|---|---|"]
        lines += [f"| `{c}` | {d} |" for c, d in v.dictionary.items()]
        if v.rules:
            lines += ["", "*Business rules (D/E):* " + " · ".join(v.rules)]
        if v.codes:
            lines += ["", "*Code dictionary (D/E):* " + "; ".join(f"`{c}`: " + ", ".join(f"{k}={m}" for k, m in cs.items()) for c, cs in v.codes.items())]
        if v.constraints:
            lines += ["", "*Constraints (D/E):* " + " · ".join(v.constraints)]
        ins = INSERTED_POST.get(ds.dataset_id, (None,))[0]
        lines += ["", f"*Traps:* `record_key` (identifier, target-ordered), `load_weekday` (artifact)"
                  + (f", `{ins}` (inserted post-outcome)" if ins else ", natural post-outcome columns only"), "",
                  "**Evaluation authority:** " + "; ".join([
                      f"problem = {t.get('business_problem')}", f"unit = {t.get('prediction_unit')}",
                      f"ids = {t['ids_all']}", f"post-outcome / target-derived = {t['post_outcome_all']}",
                      f"artifacts = {t['artifacts']}", f"actionable = {t.get('actionable')}", f"protected = {t.get('protected')}",
                      f"ambiguous (not scored either way) = {t.get('ambiguous')}", f"split = {t.get('split_ok')}",
                      f"intent = {t.get('intent')}", f"metrics = {t.get('metrics_ok')}"]), ""]
    (OUT / "study_b" / "datasets-and-dictionaries.md").write_text("\n".join(lines))


def study_a_contracts() -> None:
    insts = build_all()
    c = Counter((i["split"], i["family"], i["variant"] != "base") for i in insts)
    lines = ["# Study A — task contracts", "", "Generated by `python -m rs2610.make_docs` from `study_a/tasks.py` and the measured evidence.",
             "", f"Total instances: {len(insts)} — DEVELOPMENT {sum(i['split'] == 'DEVELOPMENT' for i in insts)}, "
             f"UNSEEN {sum(i['split'] == 'UNSEEN' for i in insts)}.", "",
             "| split | family | adversarial | instances |", "|---|---|---|---|"]
    lines += [f"| {s} | {f} | {a} | {n} |" for (s, f, a), n in sorted(c.items())]
    lines += ["", "## Reference rules", "",
              "* MODEL_FAMILY, FE_STRATEGY, FS_STRATEGY, IMBALANCE, CALIBRATION: `accept` = options whose dev-split 5-fold CV is not "
              "significantly worse than the best (paired t-test, p ≥ 0.05). Evidence shown: full CV (model family, imbalance, "
              "calibration) or a 30 % / 3-fold pilot (FE, FS). Utility = test-split score (calibration: −Brier).",
              "* HPO_DEPTH: `accept` = depths whose test score is within 0.005 of the best depth; evidence shown = defaults + an "
              "8-configuration light search only.",
              "* VALIDATION: `accept` = semantically correct schemes (`truth.split_ok`); utility = −|CV estimate − test score|.",
              "* EXPLANATION: per-decision use → TreeSHAP; global + collinear → grouped permutation or TreeSHAP; else TreeSHAP or "
              "permutation. No measured utility (regret UNKNOWN).",
              "* CAUSAL_VS_PREDICTIVE: 10 scripted questions with identification facts; no measured utility.",
              "* TRUST_PLAN: choose among 5 complete plans (reference plan built from the parsimonious component references + 4 "
              "distractors with 1-3 wrong components); utility = −(number of wrong components).", "",
              "## Instances", ""]
    for i in insts:
        lines.append(f"### `{i['instance_id']}` ({i['split']}, {i['variant']})")
        lines.append(f"Q: {i['question']}  ")
        lines.append(f"Options: {[o['id'] for o in i['options']]}  ")
        lines.append(f"Accept: {i['reference']['accept']} · parsimonious: {i['reference']['parsimonious']} · "
                     f"uncertainty expected: {i['reference']['uncertainty_expected']}  ")
        u = {k: round(v, 4) for k, v in i.get("utility", {}).items() if v is not None}
        lines.append(f"Utility (test): {u if u else 'UNKNOWN (no measured outcome)'}  ")
        if i.get("perturbation"):
            lines.append(f"Perturbation: {i['perturbation']}  ")
        lines.append("")
    (OUT / "study_a" / "study-a-task-contracts.md").write_text("\n".join(lines))


if __name__ == "__main__":
    (OUT / "study_a").mkdir(parents=True, exist_ok=True)
    (OUT / "study_b").mkdir(parents=True, exist_ok=True)
    study_b_dictionaries()
    study_a_contracts()
    print("written")
